head.script:
scwin.screenId = "jldstf76310";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("contRegDdtm")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// [A] 초기 목록 미해결 — jldstf76310: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.editor = undefined; try { scwin.editor = /* sdd-asis-lifecycle:begin editor — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Dext5editor("dext5editor1")/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf76310' }); }

scwin.upload = undefined; try { scwin.upload = /* sdd-asis-lifecycle:begin upload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Dext5Upload("dext5upload")/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf76310' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf76310.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_reg_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_reg_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_reg_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.reg()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf76310.btn_reg_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_frame_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_frame_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_frame_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.frame.CloseFrame()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf76310.btn_frame_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.reg
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.reg = async function () {
    /* sdd-asis-lifecycle:begin fn_reg — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const sprtRoomtitle = $c.util.getComponent('ipt_sprtRoomtitle').getValue();
    if ($.trim(sprtRoomtitle).length == 0) {
        await $c.win.alert("제목을 입력해 주세요.");
        ($c.util.getComponent('ipt_sprtRoomtitle') && $c.util.getComponent('ipt_sprtRoomtitle').setFocus ? $c.util.getComponent('ipt_sprtRoomtitle').setFocus() : ($c.util.getComponent('ipt_sprtRoomtitle') && $c.util.getComponent('ipt_sprtRoomtitle').focus ? $c.util.getComponent('ipt_sprtRoomtitle').focus() : console.warn('[sdd] focus 대상 미해결: ipt_sprtRoomtitle')));
        return;
    }
    if (DEXT5.isEmpty("dext5editor1")) {
        await $c.win.alert("내용을 입력해 주세요.");
        DEXT5.setFocusToEditor("dext5editor1");
        return;
    }
    scwin.transfer();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.transfer
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.transfer = function () {
    /* sdd-asis-lifecycle:begin fn_transfer — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    DEXT5UPLOAD.Transfer("dext5upload");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.DEXT5UPLOAD_OnTransfer_Complete
 * @author Inswave
 * @date 2026. 09. 29
 * @param dextId
 * @returns
 * @hidden N
*/
scwin.DEXT5UPLOAD_OnTransfer_Complete = function (dextId) {
    /* sdd-asis-lifecycle:begin DEXT5UPLOAD_OnTransfer_Complete — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const textNew = DEXT5UPLOAD.GetNewUploadListForText("dext5upload");
    if (textNew != null) {
        const rtn = fn_newTextToString(textNew);
        $('#ipt_attachFileInfo', $('#regForm')).val(rtn);
    }
    $('#ipt_SCREN_ID', $('#regForm')).val("/jldstf76310/jldstf76310.xml");
    $('#ipt_method', $('#regForm')).val("regSprtRoom");
    const htmlText = DEXT5.getBodyValue("dext5editor1");
    $c.util.getComponent('ipt_sprtRoomContn').setValue(htmlText);
    const notHtmlText = DEXT5.getBodyTextValue("dext5editor1");
    $c.util.getComponent('ipt_sprtRoomContnNoHtml').setValue(notHtmlText);
    $('#regForm').submit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.parentRefresh
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.parentRefresh = function () {
    /* sdd-asis-lifecycle:begin parentRefresh — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    parent.fn_search();
    /* sdd-asis-lifecycle:end */
};
